require('dotenv').config();
const { Client, GatewayIntentBits, EmbedBuilder } = require('@discordjs/discord.js');
const fetch = require('node-fetch'); // ou 'axios' se preferir

// Inicializa o cliente
const client = new Client({
    intents: [GatewayIntentBits.Guilds, GatewayIntentBits.MessageContent]
});

// --- CONFIGURAÇÃO DE COMANDOS E FORMATAÇÃO ---

// Função auxiliar para formatar embeds bonitos
function createEmbed(title, description, fields = [], thumbnailUrl = null, color = 0x5865F2) {
    const embed = new EmbedBuilder()
        .setColor(color)
        .setAuthor({ name: '📄 PDF Extractor Bot' })
        .setTitle(title)
        .setDescription(description);

    if (thumbnailUrl) embed.setThumbnail(thumbnailUrl);

    // Adiciona campos organizados
    if (fields.length > 0) {
        embed.addFields(fields);
    } else {
        embed.addFields({ name: 'Nenhum campo extra disponível.', inline: false });
    }

    return embed;
}

// --- LÓGICA DO BOT ---

client.on('ready', () => {
    console.log(`Bot logado como ${client.user.tag}`);

    // Registra os comandos personalizados (Slash Commands)
    // Nota: Em produção, geralmente usa-se o comando /register para cadastrar rotinas
    client.application.commands.set([
        new commands.NewCommand({
            data: {
                name: "new",
                description: "Cria um novo documento para processamento."
            },
            execute: async (interaction) => {
                await interaction.reply({ content: "Comando 'new' executado!", ephemeral: true });
            }
        }),
        new commands.NewCommand({
            data: {
                name: "process",
                description: "Processa um link de PDF fornecido pelo usuário.",
            },
            execute: async (interaction) => {
                // Verifica se o usuário forneceu o link
                const link = interaction.options.getString('pdfLink');

                if (!link) {
                    return await interaction.reply({ 
                        content: "Por favor, forneça o link do PDF usando o formato: `!process <link>`", 
                        ephemeral: true 
                    });
                }

                try {
                    // 1. Chamada para sua API externa
                    const response = await fetch(link);

                    if (!response.ok) {
                        throw new Error("Falha ao acessar o link do PDF.");
                    }

                    // 2. Extrair dados (Simulando a resposta JSON da sua API)
                    // Aqui você faria um POST para sua API real com o link
                    // Exemplo: const data = await fetch('https://api.sua.com/process?url=' + link);
                    // Para demonstração, assumindo que sua API retorna JSON direto ou você faz o POST:

                    /* 
                       Exemplo prático com POST para sua API:
                       const formData = new URLSearchParams();
                       formData.append('url', link);
                       const apiRes = await fetch(PDF_API_URL, { method: 'POST', body: formData });
                       const pdfData = await apiRes.json();
                    */

                    // Simulando dados retornados pela sua API (substitua isso pelos dados reais)
                    const simulatedPdfData = {
                        titulo: "Relatório Anual 2023",
                        autor: "Departamento Financeiro",
                        palavrasChave: ["Financeiro", "Anual", "Lucro"],
                        resumo: "Este relatório detalha as finanças do ano passado...",
                        paginaAtual: 1,
                        totalPaginas: 45
                    };

                    // 3. Formata a resposta bonita no Discord
                    const embed = createEmbed(
                        "✅ PDF Processado com Sucesso!",
                        `O documento foi analisado.\n\n${simulatedPdfData.resumo}`,
                        [
                            { name: "Título", value: simulatedPdfData.titulo, inline: true },
                            { name: "Autor", value: simulatedPdfData.autor, inline: true },
                            { name: "Total de Páginas", value: `${simulatedPdfData.totalPaginas} pág`, inline: true },
                            { name: "Palavras-chave", value: simulatedPdfData.palavrasChave.join(", "), inline: false }
                        ]
                    );

                    await interaction.reply({ embeds: [embed], ephemeral: true });

                } catch (error) {
                    console.error(error);
                    await interaction.reply({ content: "❌ Ocorreu um erro ao processar o PDF. Tente novamente.", ephemeral: true });
                }
            }
        })
    ]);
});

client.login(process.env.DISCORD_TOKEN);

// Classe simples para registrar comandos (Slash Commands)
class NewCommand {
    constructor(data) {
        this.data = data;
    }
}
```

